"""Generate the blog pages from blogs/posts/*.md.

Every post is a Markdown file with a small front matter block:

    ---
    title: Bring On the Robot War
    date: 2026-10-17
    draft: false
    image: blogs/images/robot-war-crowd.jpg
    image_alt: A crowd facing giant robots
    ---
    Text in **Markdown**...

- The file name (without .md) is the URL: blogs/posts/robot-war.md -> /blogs/robot-war/
- Posts with "draft: true" are not published.
- "image" (optional) is a picture in blogs/images, shown on top of the post, in the
  list and as the preview when the link is shared.
- Writes blogs/index.html (list of posts) and blogs/<slug>/index.html (one per post),
  and removes pages of posts that no longer exist.
"""
import datetime
import html
import re
import shutil
from pathlib import Path

import markdown

ROOT = Path(__file__).resolve().parents[2]
BLOGS_DIR = ROOT / "blogs"
POSTS_DIR = BLOGS_DIR / "posts"
MARKER = "<!-- generated by .github/scripts/generate_blogs.py -->"
SLUG = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")
IMAGE = re.compile(r"^blogs/images/[A-Za-z0-9._-]+\.(?:jpg|jpeg|png|webp|gif)$")
SITE_URL = "https://ivkalu.com"
EXCERPT_LENGTH = 220


def parse(path):
    text = path.read_text(encoding="utf-8").replace("\r\n", "\n")
    meta = {}
    body = text
    if text.startswith("---\n"):
        end = text.find("\n---", 4)
        if end != -1:
            for line in text[4:end].splitlines():
                key, sep, value = line.partition(":")
                if sep:
                    meta[key.strip().lower()] = value.strip()
            body = text[end + 4:].lstrip("\n")
    return meta, body


def excerpt(body):
    for block in body.split("\n\n"):
        block = block.strip()
        if block and not block.startswith(("#", "```", "![", ">", "<")):
            plain = re.sub(r"[*_`~]|\[([^\]]*)\]\([^)]*\)", lambda m: m.group(1) or "", block)
            plain = " ".join(plain.split())
            return plain if len(plain) <= EXCERPT_LENGTH else plain[:EXCERPT_LENGTH].rsplit(" ", 1)[0] + "…"
    return ""


def format_date(value):
    try:
        return datetime.date.fromisoformat(value).strftime("%B %-d, %Y")
    except ValueError:
        return value


def page(title, description, depth, header, content, image=None):
    up = "../" * depth
    image_meta = (
        f'\n    <meta property="og:image" content="{SITE_URL}/{html.escape(image)}">'
        '\n    <meta name="twitter:card" content="summary_large_image">'
        if image else ""
    )
    return f"""<!DOCTYPE html>
{MARKER}
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>{html.escape(title)}</title>
    <meta name="description" content="{html.escape(description)}">
    <meta property="og:title" content="{html.escape(title)}">
    <meta property="og:description" content="{html.escape(description)}">{image_meta}
    <link href="https://fonts.googleapis.com/css2?family=Roboto:wght@700&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">
    <link rel="stylesheet" href="{up}assets/css/portfolio.css">
    <link rel="stylesheet" href="{up}assets/css/custom.css">
    <link rel="stylesheet" href="{up}assets/css/blog.css">
</head>
<body>
    <header>
{header}
    </header>
{content}
</body>
</html>
"""


def main():
    posts = []
    for path in sorted(POSTS_DIR.glob("*.md")):
        slug = path.stem
        if not SLUG.match(slug) or slug == "posts":
            print(f"Skipping {path.name}: the file name must be lowercase letters, digits and dashes")
            continue
        meta, body = parse(path)
        if meta.get("draft", "false").lower() == "true":
            continue
        image = meta.get("image", "")
        if image and not (IMAGE.match(image) and (ROOT / image).is_file()):
            print(f"{path.name}: image {image!r} not found in blogs/images, ignoring it")
            image = ""
        posts.append({
            "image": image,
            "image_alt": meta.get("image_alt", ""),
            "slug": slug,
            "title": meta.get("title") or slug,
            "date": meta.get("date", ""),
            "body": body,
        })
    posts.sort(key=lambda p: (p["date"], p["slug"]), reverse=True)

    # Remove pages of deleted or unpublished posts (only folders this script made)
    published = {p["slug"] for p in posts}
    for folder in BLOGS_DIR.iterdir():
        index = folder / "index.html"
        if folder.is_dir() and folder.name not in published and index.is_file() and MARKER in index.read_text(encoding="utf-8"):
            shutil.rmtree(folder)

    for post in posts:
        content_html = markdown.markdown(post["body"], extensions=["extra", "sane_lists", "smarty"])
        header = f"""        <h1 class="post-title">{html.escape(post["title"])}</h1>
        <p class="post-date">{html.escape(format_date(post["date"]))}</p>
        <div class="contact">
            <a href="../"><i class="fas fa-arrow-left"></i> All posts</a>
            <a href="../../index.html"><i class="fas fa-house"></i> Portfolio</a>
        </div>"""
        hero = (
            f'        <img class="post-hero" src="../../{html.escape(post["image"])}" alt="{html.escape(post["image_alt"])}">\n'
            if post["image"] else ""
        )
        content = f"""    <section class="post">
{hero}        <article>
{content_html}
        </article>
    </section>"""
        folder = BLOGS_DIR / post["slug"]
        folder.mkdir(exist_ok=True)
        (folder / "index.html").write_text(
            page(post["title"] + " | Luka Ivanković", excerpt(post["body"]), 2, header, content, post["image"]),
            encoding="utf-8")

    cards = []
    for p in posts:
        thumb = f'                <img class="post-thumb" src="../{html.escape(p["image"])}" alt="">\n' if p["image"] else ""
        cards.append(f"""        <a class="post-link" href="{p["slug"]}/">
            <div class="project">
{thumb}                <p class="post-list-title"><strong>{html.escape(p["title"])}</strong></p>
                <p class="post-list-date">{html.escape(format_date(p["date"]))}</p>
                <p>{html.escape(excerpt(p["body"]))}</p>
            </div>
        </a>""")
    items = "\n".join(cards) or "        <p>Nothing here yet.</p>"
    header = """        <h1>Blog</h1>
        <div class="contact">
            <a href="../index.html"><i class="fas fa-house"></i> Portfolio</a>
            <a href="../music.html"><i class="fas fa-music"></i> Music</a>
        </div>"""
    content = f"""    <section class="post-list">
{items}
    </section>"""
    (BLOGS_DIR / "index.html").write_text(
        page("Blog | Luka Ivanković", "Posts by Luka Ivanković", 1, header, content), encoding="utf-8")
    print(f"Wrote blogs/index.html with {len(posts)} posts")


if __name__ == "__main__":
    main()
